# Trend-adjusted mediation checks for Chapter 3.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(readr, dplyr, tibble, mediation, sandwich, lmtest)
select <- dplyr::select

PROJECT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), "..")) else getwd()
})
YEARS <- 1979:2025
norm01 <- function(x) (x - min(x, na.rm=TRUE)) / (max(x, na.rm=TRUE)-min(x, na.rm=TRUE))

# Professionalisation PC1: same components and current calibrated staffing series as 41e/41o.
career_obs <- bind_rows(
  tribble(~year,~pct, 1979,3.0, 1983,4.5, 2010,14.0, 2015,17.0, 2019,21.0),
  tribble(~year,~pct, 1987,5.4, 1992,7.3, 1997,9.5, 2001,10.5, 2005,14.1)
) |> arrange(year)
career <- tibble(year=YEARS) |> mutate(obs=sapply(year, function(y) max(career_obs$year[career_obs$year<=y])),
  career_pct=career_obs$pct[match(obs, career_obs$year)])
sp <- read_csv(file.path(PROJECT,"data/raw/spads_DATA_ENTRY.csv"),show_col_types=FALSE) |> filter(year<=2025)
spads <- tibble(year=YEARS,n_spads=approx(sp$year,sp$n_spads,xout=YEARS,rule=2)$y)
ip <- read_csv(file.path(PROJECT,"data/processed/ipsa_staffing_annual.csv"),show_col_types=FALSE) |>
  select(year=cal_year,staffing=mean_staffing_real_2015)
pre <- read_csv(file.path(PROJECT,"data/processed/staffing_pre2010_calibrated_butler.csv"),show_col_types=FALSE) |>
  filter(!is.na(real_2015_mean)) |> select(year,staffing=real_2015_mean)
st <- bind_rows(pre,ip) |> arrange(year)
staff <- tibble(year=YEARS) |> mutate(obs=sapply(year,function(y) max(st$year[st$year<=y])),
  staffing=st$staffing[match(obs,st$year)])
prof <- tibble(year=YEARS) |> left_join(career |> select(year,career_pct),by="year") |>
  left_join(spads,by="year") |> left_join(staff |> select(year,staffing),by="year") |>
  mutate(career=norm01(career_pct),spads=norm01(n_spads),staffing=norm01(staffing))
pca <- prcomp(prof |> select(career,spads,staffing),scale.=TRUE,center=TRUE)
prof$prof_pc1 <- pca$x[,1]

trust <- read_csv(file.path(PROJECT,"data/processed/trust_extended_1979_2025.csv"),show_col_types=FALSE) |>
  select(year,trust_pct)
turb <- read_csv(file.path(PROJECT,"../composite_canonical/canonical_pc1_1979_2025.csv"),show_col_types=FALSE) |>
  select(year,turb_pc1=PC1_index)
d <- turb |> inner_join(trust,by="year") |> inner_join(prof |> select(year,prof_pc1),by="year") |>
  arrange(year) |> mutate(t=year-mean(year),t2=t^2,prof2=prof_pc1^2)

tidy <- function(mod,term,spec,equation,se="OLS") {
  z <- if (se=="HAC") coeftest(mod,vcov=NeweyWest(mod,lag=1,prewhite=FALSE)) else summary(mod)$coefficients
  tibble(spec=spec,equation=equation,term=term,estimate=z[term,1],std_error=z[term,2],
    statistic=z[term,3],p_value=z[term,4],se_type=se)
}
res <- list(); log <- character()
add <- function(x) res[[length(res)+1]] <<- x

for (spec in c("baseline","trend_adjusted")) {
  if (spec=="baseline") {
    mm <- lm(trust_pct~prof_pc1,data=d)
    yy <- lm(turb_pc1~prof_pc1+prof2+trust_pct,data=d)
    tt <- lm(turb_pc1~prof_pc1+prof2,data=d)
  } else {
    mm <- lm(trust_pct~prof_pc1+t+t2,data=d)
    yy <- lm(turb_pc1~prof_pc1+prof2+trust_pct+t+t2,data=d)
    tt <- lm(turb_pc1~prof_pc1+prof2+t+t2,data=d)
  }
  for (se in c("OLS","HAC")) {
    add(tidy(mm,"prof_pc1",spec,"trust",se)); add(tidy(yy,"prof_pc1",spec,"outcome_direct",se))
    add(tidy(yy,"prof2",spec,"outcome_direct",se)); add(tidy(yy,"trust_pct",spec,"outcome_direct",se))
    add(tidy(tt,"prof_pc1",spec,"outcome_total",se)); add(tidy(tt,"prof2",spec,"outcome_total",se))
  }
  log <- c(log,paste0("\n=== ",spec," ==="),capture.output(summary(mm)),capture.output(summary(yy)),
    sprintf("Product a*b = %.5f",coef(mm)["prof_pc1"]*coef(yy)["trust_pct"]))
  if (spec=="trend_adjusted") {
    set.seed(42); med <- mediate(mm,yy,treat="prof_pc1",mediator="trust_pct",sims=5000)
    log <- c(log,capture.output(summary(med)))
  }
}

# First differences remove level trends and estimate change-on-change paths.
dd <- d |> mutate(d_prof=prof_pc1-lag(prof_pc1),d_trust=trust_pct-lag(trust_pct),
  d_turb=turb_pc1-lag(turb_pc1)) |> filter(!is.na(d_prof))
mm <- lm(d_trust~d_prof,data=dd); yy <- lm(d_turb~d_prof+d_trust,data=dd); tt <- lm(d_turb~d_prof,data=dd)
for (se in c("OLS","HAC")) {
  add(tidy(mm,"d_prof","first_difference","trust",se)); add(tidy(yy,"d_prof","first_difference","outcome_direct",se))
  add(tidy(yy,"d_trust","first_difference","outcome_direct",se)); add(tidy(tt,"d_prof","first_difference","outcome_total",se))
}
log <- c(log,"\n=== first_difference ===",capture.output(summary(mm)),capture.output(summary(yy)),
  sprintf("Product a*b = %.5f",coef(mm)["d_prof"]*coef(yy)["d_trust"]))

write_csv(bind_rows(res),file.path(PROJECT,"data/processed/ch3_mediation_time_trend_results.csv"))
writeLines(log,file.path(PROJECT,"data/processed/ch3_mediation_time_trend_results.txt"))
cat(paste(log,collapse="\n"))
